<script setup lang="ts">import type { AnalyticsProfileField, AnalyticsProfileSection } from "~/types/analytics"; import { formatAnalyticsCurrency,formatAnalyticsNumber } from "~/lib/analytics-format"; defineProps<{section:AnalyticsProfileSection}>(); function display(field:AnalyticsProfileField){if(field.value===null||field.value===undefined||field.value==="")return field.displayValue; if(field.dataType==="number"&&/omzet|aset/i.test(field.fieldId))return `${formatAnalyticsCurrency(Number(field.value))} (dilaporkan)`; if(field.dataType==="number")return formatAnalyticsNumber(Number(field.value)); return field.displayValue}</script>
<template><section :id="`profile-${section.id}`" class="rounded-lg border bg-card p-4" :aria-labelledby="`profile-${section.id}-title`"><h2 :id="`profile-${section.id}-title`" class="mb-3 font-bold">{{ section.label }}</h2><dl class="grid gap-3 sm:grid-cols-2"><div v-for="field in section.fields" :key="field.fieldId" class="border-b border-border/60 pb-2"><dt class="text-xs text-muted-foreground">{{ field.label }}</dt><dd class="mt-1 text-sm" :class="{'text-muted-foreground':field.qualityStatus!=='reported'}">{{ display(field) }}</dd></div></dl></section></template>
